-- Registers the media workflow-I/O kinds produced by the matrx-ai media nodes:
--   generated_image_set  <- ai.generate_image           (GenerateImageOutput)
--   generated_video_set  <- ai.generate_video/.edit_video/.extend_video (GenerateVideoOutput)
--   generated_audio      <- ai.text_to_speech           (TextToSpeechOutput)
-- Schemas are model_json_schema() output — never hand-written. Change a model
-- and the kind moves with it in the same commit.

insert into content_ir.kind_definition
  (kind, label, authoring_owner, data, emitted_json_schema, is_active, visibility, organization_id, metadata)
select 'generated_image_set', 'Generated Image Set', 'python', null,
       $mtx${"$defs": {"AiModelUsage": {"additionalProperties": false, "description": "Per-model token/cost breakdown — one entry in :class:`AiUsage.models`.\n\nClosed shape, one canonical key-set across every producer. ``cost_usd``\nmatches the top-level ``AiUsage.cost_usd`` (this unified a prior divergence\nwhere graph_nodes wrote ``cost`` while the podcast aggregator wrote\n``cost_usd``). ``api`` / ``request_count`` default to ``\"\"`` / ``0`` for\nproducers that don't track them.", "properties": {"input_tokens": {"default": 0, "title": "Input Tokens", "type": "integer"}, "output_tokens": {"default": 0, "title": "Output Tokens", "type": "integer"}, "total_tokens": {"default": 0, "title": "Total Tokens", "type": "integer"}, "cost_usd": {"default": 0.0, "title": "Cost Usd", "type": "number"}, "request_count": {"default": 0, "title": "Request Count", "type": "integer"}, "api": {"default": "", "title": "Api", "type": "string"}}, "title": "AiModelUsage", "type": "object"}, "AiUsage": {"description": "Aggregated token / cost usage for the run.\n\nEvery constructor in the package (``_extract_usage`` below and the\npodcast pipeline's stage aggregators) sets only the declared fields, so\nthe model is closed — no ``extra=\"allow\"``. Per-model breakdown values are\ntyped as :class:`AiModelUsage`: the two producer shapes were unified onto\none canonical key-set (``cost_usd`` everywhere), so this is a precise\ncontract, not an open ``dict[str, JsonValue]``.", "properties": {"input_tokens": {"default": 0, "description": "Total input tokens billed across the run.", "title": "Input Tokens", "type": "integer"}, "output_tokens": {"default": 0, "description": "Total output tokens billed across the run.", "title": "Output Tokens", "type": "integer"}, "total_tokens": {"default": 0, "description": "Combined input and output token count across the run.", "title": "Total Tokens", "type": "integer"}, "cost_usd": {"default": 0.0, "description": "Total estimated provider cost in US dollars.", "title": "Cost Usd", "type": "number"}, "models": {"additionalProperties": {"$ref": "#/$defs/AiModelUsage"}, "description": "Per-model usage breakdown keyed by canonical model name.", "title": "Models", "type": "object"}}, "title": "AiUsage", "type": "object"}, "GeneratedImage": {"properties": {"file_id": {"anyOf": [{"type": "string"}, {"type": "null"}], "default": null, "description": "cld_files id of the generated image — the durable handle. Pass this between nodes and re-mint any URL from it; never store a signed URL.", "title": "File Id"}, "path": {"anyOf": [{"type": "string"}, {"type": "null"}], "default": null, "description": "Local filesystem path, when the provider wrote one.", "title": "Path"}, "url": {"anyOf": [{"type": "string"}, {"type": "null"}], "default": null, "description": "Inline-render URL for the image. Permanent for a public image, short-lived for a personal one — re-resolve from file_id on expiry.", "title": "Url"}, "cdn_url": {"anyOf": [{"type": "string"}, {"type": "null"}], "default": null, "description": "Permanent CDN URL, present only when the image is public.", "title": "Cdn Url"}, "signed_url": {"anyOf": [{"type": "string"}, {"type": "null"}], "default": null, "description": "Expiring inline URL, present only for a non-public image.", "title": "Signed Url"}, "data_b64": {"anyOf": [{"type": "string"}, {"type": "null"}], "default": null, "description": "Base64 image bytes, only when the provider returned no persisted file.", "title": "Data B64"}, "mime_type": {"anyOf": [{"type": "string"}, {"type": "null"}], "default": null, "description": "Canonical MIME type of the encoded image.", "title": "Mime Type"}, "size_bytes": {"anyOf": [{"type": "integer"}, {"type": "null"}], "default": null, "description": "Encoded image size in bytes.", "title": "Size Bytes"}, "width": {"anyOf": [{"type": "integer"}, {"type": "null"}], "default": null, "description": "Image width in pixels.", "title": "Width"}, "height": {"anyOf": [{"type": "integer"}, {"type": "null"}], "default": null, "description": "Image height in pixels.", "title": "Height"}, "seed": {"anyOf": [{"type": "integer"}, {"type": "null"}], "default": null, "description": "Seed the provider used, when it reports one.", "title": "Seed"}}, "title": "GeneratedImage", "type": "object"}}, "additionalProperties": false, "properties": {"images": {"description": "Every image the provider returned, in order.", "items": {"$ref": "#/$defs/GeneratedImage"}, "title": "Images", "type": "array"}, "count": {"default": 0, "description": "How many images were generated.", "title": "Count", "type": "integer"}, "model": {"description": "Image model id that produced the images.", "title": "Model", "type": "string"}, "usage": {"$ref": "#/$defs/AiUsage"}}, "required": ["model"], "title": "GenerateImageOutput", "type": "object"}$mtx$::jsonb,
       false, 'public', '39c38960-d30c-4840-b0c1-c9960de95582',
       $mtx${"family": "workflow_io", "generic": false, "category": "pure", "description": "One or more generated images with their canonical file identity and durable URLs."}$mtx$::jsonb
where not exists (
  select 1 from content_ir.kind_definition
  where organization_id = '39c38960-d30c-4840-b0c1-c9960de95582' and kind = 'generated_image_set' and deleted_at is null);

insert into content_ir.kind_example
  (kind_definition_id, kind_version, data, label, source, is_canonical, validation_status, validated_at, organization_id)
select kd.id, kd.version,
       $mtx${"images": [{"file_id": "db22f2a2-9548-4eb7-946b-19b267bdee09", "url": "https://cdn.matrxserver.com/4cf62e4e-2679-484f-b652-034e697418df/db22f2a2-9548-4eb7-946b-19b267bdee09?v=84f485d6", "cdn_url": "https://cdn.matrxserver.com/4cf62e4e-2679-484f-b652-034e697418df/db22f2a2-9548-4eb7-946b-19b267bdee09?v=84f485d6", "mime_type": "image/jpeg", "width": 1536, "height": 1024}], "count": 1, "model": "flux-1.1-pro", "usage": {"cost_usd": 0.04}}$mtx$::jsonb,
       'Canonical example', 'authored', true, 'passed', now(), '39c38960-d30c-4840-b0c1-c9960de95582'
from content_ir.kind_definition kd
where kd.organization_id = '39c38960-d30c-4840-b0c1-c9960de95582' and kd.kind = 'generated_image_set' and kd.deleted_at is null
  and not exists (
    select 1 from content_ir.kind_example e
    where e.kind_definition_id = kd.id and e.is_canonical and e.deleted_at is null);

insert into content_ir.kind_definition
