select 'generated_video_set', 'Generated Video Set', 'python', null,
       $mtx${"$defs": {"AiModelUsage": {"additionalProperties": false, "description": "Per-model token/cost breakdown — one entry in :class:`AiUsage.models`.\n\nClosed shape, one canonical key-set across every producer. ``cost_usd``\nmatches the top-level ``AiUsage.cost_usd`` (this unified a prior divergence\nwhere graph_nodes wrote ``cost`` while the podcast aggregator wrote\n``cost_usd``). ``api`` / ``request_count`` default to ``\"\"`` / ``0`` for\nproducers that don't track them.", "properties": {"input_tokens": {"default": 0, "title": "Input Tokens", "type": "integer"}, "output_tokens": {"default": 0, "title": "Output Tokens", "type": "integer"}, "total_tokens": {"default": 0, "title": "Total Tokens", "type": "integer"}, "cost_usd": {"default": 0.0, "title": "Cost Usd", "type": "number"}, "request_count": {"default": 0, "title": "Request Count", "type": "integer"}, "api": {"default": "", "title": "Api", "type": "string"}}, "title": "AiModelUsage", "type": "object"}, "AiUsage": {"description": "Aggregated token / cost usage for the run.\n\nEvery constructor in the package (``_extract_usage`` below and the\npodcast pipeline's stage aggregators) sets only the declared fields, so\nthe model is closed — no ``extra=\"allow\"``. Per-model breakdown values are\ntyped as :class:`AiModelUsage`: the two producer shapes were unified onto\none canonical key-set (``cost_usd`` everywhere), so this is a precise\ncontract, not an open ``dict[str, JsonValue]``.", "properties": {"input_tokens": {"default": 0, "description": "Total input tokens billed across the run.", "title": "Input Tokens", "type": "integer"}, "output_tokens": {"default": 0, "description": "Total output tokens billed across the run.", "title": "Output Tokens", "type": "integer"}, "total_tokens": {"default": 0, "description": "Combined input and output token count across the run.", "title": "Total Tokens", "type": "integer"}, "cost_usd": {"default": 0.0, "description": "Total estimated provider cost in US dollars.", "title": "Cost Usd", "type": "number"}, "models": {"additionalProperties": {"$ref": "#/$defs/AiModelUsage"}, "description": "Per-model usage breakdown keyed by canonical model name.", "title": "Models", "type": "object"}}, "title": "AiUsage", "type": "object"}, "GeneratedVideo": {"properties": {"path": {"anyOf": [{"type": "string"}, {"type": "null"}], "default": null, "title": "Path"}, "url": {"anyOf": [{"type": "string"}, {"type": "null"}], "default": null, "title": "Url"}, "mime_type": {"anyOf": [{"type": "string"}, {"type": "null"}], "default": null, "title": "Mime Type"}, "duration_seconds": {"anyOf": [{"type": "number"}, {"type": "null"}], "default": null, "title": "Duration Seconds"}}, "title": "GeneratedVideo", "type": "object"}}, "additionalProperties": false, "properties": {"videos": {"items": {"$ref": "#/$defs/GeneratedVideo"}, "title": "Videos", "type": "array"}, "count": {"default": 0, "title": "Count", "type": "integer"}, "model": {"title": "Model", "type": "string"}, "usage": {"$ref": "#/$defs/AiUsage"}}, "required": ["model"], "title": "GenerateVideoOutput", "type": "object"}$mtx$::jsonb,
       false, 'public', '39c38960-d30c-4840-b0c1-c9960de95582',
       $mtx${"family": "workflow_io", "generic": false, "category": "pure", "description": "One or more generated video clips with their durable URLs."}$mtx$::jsonb
where not exists (
  select 1 from content_ir.kind_definition
  where organization_id = '39c38960-d30c-4840-b0c1-c9960de95582' and kind = 'generated_video_set' and deleted_at is null);

insert into content_ir.kind_example
